import logging

logger = logging.getLogger(APP_NAME)
logging.basicConfig(level=logging.DEBUG)

def guess_file_mime_type(path):
    _, ext = os.path.splitext(path)
    ext = ext.lower()

    mime_map = {
        '.wav':  'audio/x-wav',
        '.psd':  'image/x-psd',
        '.jpg':  'image/jpeg',
        '.png':  'image/png',
        '.gif':  'image/gif'
    }

    return mime_map.get(ext, None)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            self.type = guess_file_mime_type(path)
            if not self.type:
                mimetypes.init()
                self.type = mimetypes.guess_type(path)[0]


    @staticmethod
    def get_objects(path):
        objects = []
        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))
        return objects


