        # readable. Log it and move on, otherwise we might be masking other errors later on.
        ex.filename = None    # that way we can't get a "NoneType' object has no attribute 'join' error if we ignoreability succeeded but something else went wrong
        # TODO: After moving to python3, we can change this to an empty log message, otherwise we get a cryptic "...%s" % () error
        import logging; logger = logging.getLogger("config_check"); logger.error("Warning: ", str(ex))

    try:
        ks_configs = config_file.items('keystone_authtoken')
    except ConfigParser.NoSectionError as ex:
        ex.filename = None    # that way we can't get a "NoneType' object has no attribute 'join' error if we ignoreability succeeded but something else went wrong
        logging.info("Warning: ", str(ex))
        ks_configs = []
    global_config.update(ks_configs)

    return auth_filter_factory(global_config)

